function customer_money(float $value, string $currency, string $language): string { $decimal = $language === 'en' ? '.' : ','; $thousand = $language === 'en' ? ',' : '.'; $symbol = $currency === 'EUR' ? '€' : $currency; return number_format($value, 2, $decimal, $thousand).' '.$symbol; }
function customer_date(?string $date, string $language): string { if (!$date || !valid_date($date)) return '–'; $format = $language === 'en' ? 'm/d/Y' : 'd/m/Y'; if ($language === 'de') $format = 'd.m.Y'; return (new DateTimeImmutable($date))->format($format); }
function customer_datetime(?string $date, string $language): string { if (!$date) return '–'; try { $d = new DateTimeImmutable($date); return $d->format($language === 'de' ? 'd.m.Y H:i' : 'd/m/Y H:i'); } catch (Throwable) { return '–'; } }
function customer_status_text(string $status, array $t): string { return $t[$status] ?? ($status === 'paid' ? ($t['paid_status'] ?? 'Paid') : ($t['open_status'] ?? $status)); }
if ($booking) {
    $people = (int)$booking['adults'] + (int)$booking['children'] + (int)$booking['babies'];
    $currency = (string)($booking['currency'] ?? 'EUR');
    $paid = (float)($booking['paid_total'] ?? $booking['paid_amount'] ?? 0);
    $open = (float)($booking['open_total'] ?? max(0, (float)$booking['total_price'] - $paid));
    $hasOverdue = false;
    foreach (($booking['payment_schedule'] ?? []) as $row) {
        if (($row['status'] ?? '') === 'overdue') {
            $hasOverdue = true;
            break;
        }
    }
    $needsClarification = !empty($booking['needs_clarification']);
    $workflowLabel = (string)($booking['workflow_status_label'] ?? '');
    $timeline = [
        ['title' => $needsClarification ? $t['clarification'] : $t['confirmed'], 'text' => $needsClarification ? ($workflowLabel ?: $t['clarification_note']) : customer_datetime($booking['confirmed_at'] ?? null, $lang), 'class' => $needsClarification ? 'warn' : 'done'],
        ['title' => $t['email_sent'], 'text' => customer_datetime($booking['confirmation_email_sent_at'] ?? null, $lang), 'class' => !empty($booking['confirmation_email_sent_at']) ? 'done' : ''],
        ['title' => $open <= 0.01 ? $t['payment_done'] : $t['payment_open'], 'text' => customer_money($open, $currency, $lang).' '.$t['open'], 'class' => $open <= 0.01 ? 'done' : ($hasOverdue ? 'warn' : '')],
        ['title' => $t['portal'], 'text' => $t['last_status'], 'class' => 'done'],
    ];
    $documents = DocumentTemplateService::portalDocuments($booking, $token);
    $actions = [];
    if ($checkinUrl !== '') {
        $actions[] = ['href' => $checkinUrl, 'title' => $checkinText['title'], 'text' => $checkinText['cta']];
    }
    if (!empty($documents[0]['href'])) {
        $actions[] = ['href' => (string)$documents[0]['href'], 'title' => $t['documents'], 'text' => $t['download']];
    }
    $emails = DocumentTemplateService::portalEmails($booking);
    $portalHtml = DocumentTemplateService::renderPublicCustomerPortal($lang, $booking, [
        'portal_title' => (string)($booking['reference'] ?? 'Kundenbereich'),
        'portal_subtitle' => (string)$booking['guest_name'].' - '.$t['welcome'],
        'portal_url' => 'kunde.php?token='.rawurlencode($token),
        'hero_url' => $checkinUrl,
        'checkin_url' => $checkinUrl,
        'booking_status' => $needsClarification ? $t['clarification'] : ($workflowLabel ?: (string)($booking['status'] ?? '')),
        'payment_status' => customer_status_text($hasOverdue ? 'overdue' : (string)($booking['payment_status'] ?? 'open'), $t),
        'timeline' => $timeline,
        'documents' => $documents,
        'actions' => $actions,
        'emails' => $emails,
        'payment_schedule' => is_array($booking['payment_schedule'] ?? null) ? $booking['payment_schedule'] : [],
        'payments' => is_array($booking['payments'] ?? null) ? $booking['payments'] : [],
        'checkin' => is_array($checkinSummary ?? null) ? $checkinSummary : [],
        'property_name' => (string)($booking['apartment_type_name'] ?? ''),
        'apartment_name' => trim((string)($booking['apartment_type_name'] ?? '').' '.(string)($booking['apartment_name'] ?? '')),
        'adults' => (string)$people,
    ]);
    if (is_string($portalHtml) && $portalHtml !== '') {
        echo $portalHtml;
        exit;
    }
}
