:root{--blue:#2563eb;--cyan:#38bdf8;--navy:#0f172a;--ink:#172033;--muted:#64748b;--line:#dbe6f1;--bg:#edf4fb;--ok:#16a34a;--warn:#f59e0b;--bad:#dc2626;--card:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#dbeafe 0,transparent 32%),radial-gradient(circle at 100% 10%,#ccfbf1 0,transparent 28%),linear-gradient(180deg,#f8fbff,#edf4fb);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",Arial,sans-serif}.wrap{width:min(1180px,calc(100% - 28px));margin:22px auto 42px}.hero{position:relative;overflow:hidden;background:linear-gradient(135deg,#0f172a 0%,#1d4ed8 56%,#0f766e 100%);color:#fff;border-radius:30px;padding:30px;box-shadow:0 24px 80px rgba(15,23,42,.24)}.hero:after{content:"";position:absolute;right:-90px;top:-90px;width:280px;height:280px;border-radius:50%;background:rgba(255,255,255,.16)}.hero-top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;position:relative}.hero small,.eyebrow{opacity:.78;text-transform:uppercase;letter-spacing:.08em;font-size:12px;font-weight:800}.hero h1{margin:6px 0 8px;font-size:clamp(30px,5vw,52px);letter-spacing:-.04em}.hero p{margin:0;color:#dbeafe;font-size:17px}.status-pill{display:inline-flex;align-items:center;border-radius:999px;padding:9px 13px;background:rgba(255,255,255,.18);backdrop-filter:blur(10px);font-weight:900;white-space:nowrap}.status-pill.open,.status-pill.partial{background:#fffbeb;color:#92400e}.status-pill.paid,.status-pill.received{background:#dcfce7;color:#166534}.status-pill.overdue{background:#fee2e2;color:#991b1b}.hero-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:24px;position:relative}.hero-card{background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);border-radius:18px;padding:15px;min-height:88px}.hero-card span{display:block;font-size:12px;opacity:.78;margin-bottom:4px}.hero-card b{font-size:18px;line-height:1.25}.status-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:16px}.strip-step{background:#fff;border:1px solid var(--line);border-radius:18px;padding:14px;display:flex;gap:10px;align-items:center}.strip-step i{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#eff6ff;color:var(--blue);font-style:normal;font-weight:900}.strip-step.done i{background:#dcfce7;color:#166534}.strip-step.warn i{background:#fef3c7;color:#92400e}.cards{display:grid;grid-template-columns:1.15fr .85fr;gap:16px;margin-top:16px}.card{background:rgba(255,255,255,.97);border:1px solid var(--line);border-radius:24px;padding:21px;box-shadow:0 14px 40px rgba(15,23,42,.08)}.card h2{margin:0 0 14px;font-size:22px}.money-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.money-box{background:#f8fafc;border:1px solid var(--line);border-radius:17px;padding:14px}.money-box small{display:block;color:var(--muted);margin-bottom:4px}.money-box b{font-size:21px}.progress{height:14px;background:#e2e8f0;border-radius:999px;overflow:hidden;margin:14px 0 4px}.progress span{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#2563eb);border-radius:inherit}.schedule,.payments-list{display:grid;gap:10px}.payment{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;align-items:center;border:1px solid var(--line);border-radius:17px;padding:14px;background:#fff}.payment small,.muted{color:var(--muted)}.status{display:inline-flex;border-radius:999px;padding:6px 10px;background:#eff6ff;color:#1d4ed8;font-weight:900;font-size:12px}.status.overdue{background:#fef2f2;color:#b91c1c}.status.received,.status.paid{background:#ecfdf5;color:#166534}.status.waived{background:#f1f5f9;color:#475569}.status-pill.warning{background:#fffbeb;color:#92400e;border-color:#fbbf24}.strip-step.warn i{background:#f59e0b;color:#fff}.payline{display:flex;justify-content:space-between;gap:12px;border:1px solid var(--line);border-radius:15px;padding:13px;background:#f8fafc}.docs{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:11px}.doc{display:grid;gap:5px;border:1px solid var(--line);border-radius:17px;padding:16px;text-decoration:none;color:var(--ink);background:#fff}.doc:hover{border-color:var(--blue);box-shadow:0 13px 30px rgba(37,99,235,.13)}.note{margin-top:16px;background:#fffbeb;border-left:4px solid #f59e0b;padding:15px;border-radius:15px}.info-note{background:#eef6ff;border:1px solid #bfdbfe;border-radius:17px;padding:15px}.checkin-card{background:linear-gradient(135deg,#ffffff 0%,#eef6ff 100%)}.checkin-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.checkin-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.checkin-box{background:#fff;border:1px solid var(--line);border-radius:16px;padding:13px}.checkin-box small{display:block;color:var(--muted);margin-bottom:4px}.checkin-box b{font-size:17px}.portal-action{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:999px;background:#2563eb;color:#fff;text-decoration:none;font-weight:900;padding:12px 16px;box-shadow:0 14px 30px rgba(37,99,235,.22)}.portal-action:hover{background:#1d4ed8}.checkin-state{display:inline-flex;border-radius:999px;padding:8px 12px;font-weight:900;background:#eff6ff;color:#1d4ed8}.checkin-state.incomplete,.checkin-state.open{background:#fffbeb;color:#92400e}.checkin-state.reviewed,.checkin-state.submitted{background:#dcfce7;color:#166534}.error{max-width:620px;margin:10vh auto;background:#fff;border-radius:22px;padding:28px;box-shadow:0 20px 60px rgba(15,23,42,.15)}@media(max-width:960px){.cards{grid-template-columns:1fr}.hero-grid,.status-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.money-row{grid-template-columns:1fr}}@media(max-width:960px){.checkin-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.wrap{width:min(100% - 18px,1120px);margin:9px auto 28px}.hero{border-radius:20px;padding:22px}.hero-top{display:block}.hero-grid,.status-strip{grid-template-columns:1fr}.payment{grid-template-columns:1fr}.payline{display:block}.status-pill{margin-top:14px}}@media(max-width:560px){.checkin-head{display:block}.checkin-grid{grid-template-columns:1fr}.portal-action{width:100%;margin-top:12px}}
</style></head><body>
<?php if (!$booking): ?>
<main class="error"><h1><?=e($t['title'])?></h1><p><?=e($t['error'])?></p><small><?=e($error)?></small></main>
<?php else:
$people = (int)$booking['adults'] + (int)$booking['children'] + (int)$booking['babies'];
$currency = (string)($booking['currency'] ?? 'EUR');
$paid = (float)($booking['paid_total'] ?? $booking['paid_amount'] ?? 0);
$open = (float)($booking['open_total'] ?? max(0, (float)$booking['total_price'] - $paid));
$total = max(0.01, (float)$booking['total_price']);
$percent = max(0, min(100, round($paid / $total * 100)));
$payStatus = (string)($booking['payment_status'] ?? 'open');
$hasOverdue = false;
foreach (($booking['payment_schedule'] ?? []) as $row) if (($row['status'] ?? '') === 'overdue') $hasOverdue = true;
$needsClarification = !empty($booking['needs_clarification']);
$workflowLabel = (string)($booking['workflow_status_label'] ?? '');
$heroStatusClass = $needsClarification ? 'warning' : ($hasOverdue ? 'overdue' : $payStatus);
$heroStatusText = $needsClarification ? $t['clarification'] : customer_status_text($hasOverdue ? 'overdue' : $payStatus, $t);
$apartmentLabel = trim((string)($booking['apartment_code'] ?? '') . ' ' . (string)($booking['apartment_name'] ?? ''));
?>
<main class="wrap">
<section class="hero"><div class="hero-top"><div><small><?=e($t['booking'])?></small><h1><?=e((string)$booking['reference'])?></h1><p><?=e((string)$booking['guest_name'])?> · <?=e($t['welcome'])?></p></div><span class="status-pill <?=e($heroStatusClass)?>"><?=e($heroStatusText)?></span></div><div class="hero-grid"><div class="hero-card"><span><?=e($t['stay'])?></span><b><?=e(customer_date($booking['arrival'], $lang).' – '.customer_date($booking['departure'], $lang))?></b></div><div class="hero-card"><span><?=e($t['type'])?></span><b><?=e($booking['apartment_type_name'] ?? '–')?></b><br><small class="muted"><?=e($needsClarification ? $t['clarification'] : ($apartmentLabel !== '' ? $t['apartment'].': '.$apartmentLabel : ''))?></small></div><div class="hero-card"><span><?=e($t['persons'])?></span><b><?=$people?></b></div><div class="hero-card"><span><?=e($t['updated'])?></span><b><?=e(customer_datetime($booking['customer_status_updated_at'] ?? null, $lang))?></b></div></div></section>
<div class="status-strip" aria-label="<?=e($t['timeline'])?>"><div class="strip-step <?= $needsClarification ? 'warn' : 'done' ?>"><i>1</i><div><b><?=e($needsClarification ? $t['clarification'] : $t['confirmed'])?></b><br><small class="muted"><?=e($needsClarification ? ($workflowLabel ?: $t['clarification_note']) : customer_datetime($booking['confirmed_at'] ?? null, $lang))?></small></div></div><div class="strip-step <?=!empty($booking['confirmation_email_sent_at'])?'done':''?>"><i>2</i><div><b><?=e($t['email_sent'])?></b><br><small class="muted"><?=e(customer_datetime($booking['confirmation_email_sent_at'] ?? null, $lang))?></small></div></div><div class="strip-step <?=($open <= 0.01)?'done':($hasOverdue?'warn':'')?>"><i>3</i><div><b><?=e($open <= 0.01 ? $t['payment_done'] : $t['payment_open'])?></b><br><small class="muted"><?=e(customer_money($open, $currency, $lang))?> <?=e($t['open'])?></small></div></div><div class="strip-step done"><i>4</i><div><b><?=e($t['portal'])?></b><br><small class="muted"><?=e($t['last_status'])?></small></div></div></div>
<section class="card checkin-card" style="margin-top:16px"><div class="checkin-head"><div><h2><?=e($checkinText['title'])?></h2><p class="muted"><?=e($checkinText['intro'])?></p></div><div><span class="checkin-state <?=e($checkinStatus)?>"><?=e($checkinText[$checkinStatus] ?? $checkinStatus)?></span><br><a class="portal-action" href="<?=e($checkinUrl)?>">📝 <?=e($checkinText['cta'])?></a></div></div><div class="checkin-grid"><div class="checkin-box"><small><?=e($checkinText['status'])?></small><b><?=e($checkinText[$checkinStatus] ?? $checkinStatus)?></b></div><div class="checkin-box"><small><?=e($checkinText['missing'])?></small><b><?=e((string)(int)($checkinSummary['missing_count'] ?? 0))?></b></div><div class="checkin-box"><small><?=e($checkinText['guests'])?></small><b><?=e((string)(int)($checkinSummary['traveller_count'] ?? 0))?></b></div><div class="checkin-box"><small><?=e($checkinText['uploads'])?></small><b><?=e((string)(int)($checkinSummary['upload_count'] ?? 0))?></b></div><div class="checkin-box"><small><?=e($checkinText['arrival'])?></small><b><?=e((string)($checkinSummary['planned_arrival_time'] ?? '–') ?: '–')?></b></div></div><?php $missingItems = array_slice(array_map('strval', $checkinSummary['missing'] ?? []),0,6); ?><p class="muted"><?=e(($checkinStatus === 'reviewed') ? $checkinText['reviewed_note'] : (($checkinSummary['missing_count'] ?? 0) > 0 ? $checkinText['missing'].': '.implode(', ', $missingItems) : $checkinText['ready']))?></p><?php if (($checkinSummary['missing_count'] ?? 0) > 0): ?><div class="info-note"><b>Bitte ergänzen:</b><ul><?php foreach($missingItems as $m): ?><li><?=e($m)?></li><?php endforeach; ?></ul></div><?php endif; ?></section>
<section class="card" style="margin-top:16px"><h2><?=e($t['payments'])?></h2><div class="money-row"><div class="money-box"><small><?=e($t['total'])?></small><b><?=e(customer_money((float)$booking['total_price'], $currency, $lang))?></b></div><div class="money-box"><small><?=e($t['paid'])?></small><b><?=e(customer_money($paid, $currency, $lang))?></b></div><div class="money-box"><small><?=e($t['open'])?></small><b><?=e(customer_money($open, $currency, $lang))?></b></div></div><div class="progress" aria-label="<?=e($percent.'%')?>"><span style="width:<?=$percent?>%"></span></div><p class="muted"><?=e($t['status_changed'])?></p></section>
<div class="cards"><section class="card"><h2><?=e($t['next'])?></h2><div class="schedule"><?php foreach (($booking['payment_schedule'] ?? []) as $row): $status = (string)$row['status']; ?><div class="payment"><div><b><?=e($row['label'] ?: ($row['installment_type'] === 'deposit' ? $t['deposit'] : $t['remaining']))?></b><br><small><?=e($t['due'].': '.customer_date($row['due_date'] ?? null, $lang))?></small></div><b><?=e(customer_money((float)$row['amount'], $currency, $lang))?></b><span class="status <?=e($status)?>"><?=e(customer_status_text($status, $t))?></span></div><?php endforeach; ?></div></section><section class="card"><h2><?=e($t['paid_list'])?></h2><div class="payments-list"><?php if (empty($booking['payments'])): ?><p class="muted"><?=e($t['no_payments'])?></p><?php endif; foreach (($booking['payments'] ?? []) as $pay): ?><div class="payline"><span><?=e(customer_date($pay['payment_date'] ?? null, $lang))?><br><small class="muted"><?=e($pay['payment_method'] ?? '')?> <?=e($pay['reference'] ?? '')?></small></span><b><?=e(customer_money((float)$pay['amount'], $currency, $lang))?></b></div><?php endforeach; ?></div></section></div>
<section class="card" style="margin-top:16px"><h2><?=e($t['documents'])?></h2><div class="docs"><?php if (empty($booking['documents'])): ?><p><?=e($t['no_docs'])?></p><?php endif; foreach (($booking['documents'] ?? []) as $doc): ?><a class="doc" href="kunde-dokument.php?token=<?=rawurlencode($token)?>&amp;id=<?=(int)$doc['id']?>" target="_blank" rel="noopener"><b>📄 <?=e($doc['title'])?></b><small><?=e($doc['document_number'] ?? '')?></small><small><?=e($t['download'])?> · <?=e(customer_datetime($doc['generated_at'] ?? null, $lang))?></small></a><?php endforeach; ?></div></section>
<section class="card" style="margin-top:16px"><h2>E-Mails</h2><div class="docs"><?php if (empty($booking['emails'])): ?><p class="muted">Noch keine E-Mails protokolliert.</p><?php endif; foreach (($booking['emails'] ?? []) as $mail): ?><div class="doc"><b>✉️ <?=e($mail['subject'] ?? 'E-Mail')?></b><small><?=e($mail['status'] ?? '')?></small><small><?=e(customer_datetime($mail['created_at'] ?? null, $lang))?></small></div><?php endforeach; ?></div></section>
<div class="note"><b><?=e($t['important'])?></b><br><?=e($needsClarification ? $t['clarification_note'] : $t['note'])?></div>
</main>
<?php endif; ?></body></html>
